/* 统计汇总表固定列遮罩：本表不在 .list-card/.zs-table-container 内，全局
   .el-table/tr 被设为透明（透出页面底色），导致前两列 fixed 冻结层无遮挡，
   横向滚动时其它列内容会透出、与固定列文字重叠。显式给固定列（含表头、
   合计行）白色不透明底色，遮住其下方滚动内容；表体本身也置白保证与固定列一致。 */
.detail-container >>> .summary-table {
  background-color: #fff;
}
.detail-container >>> .summary-table .el-table__fixed,
.detail-container >>> .summary-table .el-table__fixed-header-wrapper,
.detail-container >>> .summary-table .el-table__fixed-footer-wrapper {
  background-color: #fff;
}
.detail-container >>> .summary-table .el-table__fixed-body-wrapper td.el-table__cell,
.detail-container >>> .summary-table .el-table__fixed-header-wrapper th.el-table__cell,
.detail-container >>> .summary-table .el-table__fixed-footer-wrapper td.el-table__cell {
  background-color: #fff;
